/// Coordinates yield-from rewrites with adjacent loop, dict, enumerate,
/// version-gate, and format-string upgrade analysis.
#[derive(Debug, Default, Clone)]
pub(crate) struct UpgradeRewriteSession {
    yield_ledger: YieldRewriteLedger,
    loop_ledger: LoopControlLedger,
    dict_ledger: DictIterationLedger,
    enumerate_ledger: EnumerateLedger,
    version_ledger: VersionGateLedger,
    format_ledger: FormatRewriteLedger,
}

impl UpgradeRewriteSession {    pub(crate) fn should_rewrite_yield_from(
