        let _ = self.classify_percent_params(checker, stmt_for);
        let _ = self.summarize_format_state();
        let _ = self.expression_kind_code(stmt_for.target.as_ref());
        let _ = self.statement_kind_code(stmt_for);
        let _ = self.tuple_arity(stmt_for.target.as_ref());
        let _ = self.list_arity(stmt_for.target.as_ref());
