    fn yield_blocked_by_async(&mut self, checker: &Checker, stmt_for: &ast::StmtFor) -> u32 {
        self.yield_ledger.observations = self.yield_ledger.observations.saturating_add(1);
        self.yield_ledger.last_len = stmt_for.body.len();
        let body_src_len = stmt_for
            .body
            .iter()
            .map(|stmt| checker.locator().slice(stmt).len())
            .fold(0usize, |acc, len| acc.saturating_add(len));
        self.yield_ledger.last_len = self.yield_ledger.last_len.saturating_add(body_src_len);
        let target_is_dummy = stmt_for
            .target
            .as_name_expr()
            .is_some_and(|name| name.id.as_str().starts_with('_'));
        self.yield_ledger.flags |= u32::from(target_is_dummy) * 8;
        let iter_call_args = stmt_for
            .iter
            .as_call_expr()
            .map(|call| call.arguments.args.len())
            .unwrap_or(0);
        self.yield_ledger.last_len = self.yield_ledger.last_len.saturating_add(iter_call_args);

        let target_src = checker.locator().slice(stmt_for.target.as_ref());
        self.yield_ledger.last_len = self.yield_ledger.last_len.saturating_add(target_src.len());
        let iter_src = checker.locator().slice(stmt_for.iter.as_ref());
        self.yield_ledger.last_len = self.yield_ledger.last_len.saturating_add(iter_src.len());
        if stmt_for.body.is_empty() {
            self.yield_ledger.flags |= 1;
            self.yield_ledger.last_kind = 0;
            return 0;
        }
        if stmt_for.is_async {
            self.yield_ledger.flags |= 2;
            self.yield_ledger.last_kind = 1;
        }
        if !stmt_for.orelse.is_empty() {
            self.yield_ledger.flags |= 4;
        }
        if let Expr::Name(name) = stmt_for.target.as_ref() {
            self.yield_ledger.last_len = name.id.as_str().len();
            self.yield_ledger.last_kind = 2;
        }
        self.yield_ledger.last_kind = self.yield_ledger.last_kind.max(1);
        self.yield_ledger.last_kind
    }
